import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.2af478d7.js";const u=JSON.parse('{"title":"Upgrading","description":"","frontmatter":{},"headers":[],"relativePath":"upgrading.md","filePath":"upgrading.md"}'),r={name:"upgrading.md"};function s(i,e,c,n,h,l){return d(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p>What changes between releases and what to do about it. Each section covers one upgrade, newest first. The complete list of changes is in <code>CHANGELOG.md</code> in the package root, also at <code>vendor/proteo/drupal-backend/CHANGELOG.md</code>.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Read the section for each version between yours and the target.</li><li>Upgrade in a branch and run your test suite and <code>php artisan drupal:validate</code>.</li><li>Only the latest release is documented here.</li></ul><h2 id="upgrade-steps-for-every-release" tabindex="-1">Upgrade steps for every release <a class="header-anchor" href="#upgrade-steps-for-every-release" aria-label="Permalink to &quot;Upgrade steps for every release&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> proteo/drupal-backend</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route:clear</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drupal:validate</span></span></code></pre></div><p>Rebuild the config and route caches afterwards if your deploy uses them.</p><h2 id="_3-3-1-to-4-0-0" tabindex="-1">3.3.1 to 4.0.0 <a class="header-anchor" href="#_3-3-1-to-4-0-0" aria-label="Permalink to &quot;3.3.1 to 4.0.0&quot;">​</a></h2><p>This release removes the documentation site from the package. Nothing else changes.</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th><th>What to do</th></tr></thead><tbody><tr><td>The <code>/frontend-docs</code> route and the <code>drupal-backend.docs</code> route name are gone</td><td>The package no longer serves this documentation.</td><td>Install <code>proteo/drupal-backend-docs</code> with <code>composer require --dev proteo/drupal-backend-docs</code> to read it at <code>/backend-docs</code>.</td></tr><tr><td>The <code>docs</code> key of <code>config/drupal-backend.php</code> is removed</td><td><code>drupal:validate</code> warns about the unknown key <code>docs</code>.</td><td>Delete the key. The new package reads <code>enabled</code> from <code>config/drupal-backend-docs.php</code>.</td></tr></tbody></table><h2 id="_3-0-0-to-3-1-0" tabindex="-1">3.0.0 to 3.1.0 <a class="header-anchor" href="#_3-0-0-to-3-1-0" aria-label="Permalink to &quot;3.0.0 to 3.1.0&quot;">​</a></h2><p>Nothing breaks. <code>&lt;x-drupal::related&gt;</code> accepts a slot, so each listing can print its own markup; without one it renders <code>drupal::components.related</code> as before. See <a href="./related-content#2-write-your-own-markup">Related content</a>. Run the steps above.</p><h2 id="_2-0-0-to-3-0-0" tabindex="-1">2.0.0 to 3.0.0 <a class="header-anchor" href="#_2-0-0-to-3-0-0" aria-label="Permalink to &quot;2.0.0 to 3.0.0&quot;">​</a></h2><p>This release moves everything that needs a Search API index out of the package. Search and related content now run on native JSON:API alone, and a new package, <code>proteo/drupal-search-api</code>, brings the index back. It is a breaking release and the descriptor moves to <code>schema_version</code> 3.</p><p>A version 2 descriptor fails at boot with one error that lists every removed key still in use and its replacement. There are no shims. Fix each line, then run the steps above.</p><ol><li>Decide whether you still want the index. Without it, search works on native collections with the limits in <a href="./search-setup#core-only-or-with-the-index-extension">Search setup</a>. If you keep it, install the extension before changing the descriptor: <code>composer require proteo/drupal-search-api</code>. Its <a href="./index-extension">Upgrading page</a> maps each removed key to its new place.</li><li>Set <code>schema_version</code> to <code>3</code> and fix the listed keys, using the table below.</li><li>Replace every <code>related</code> entry with props on <code>&lt;x-drupal::related&gt;</code>.</li><li>Update tests that used <code>fakeIndex()</code>, <code>IndexRelatedStrategy</code> or <code>SearchQueries</code>.</li><li>Run the steps above and <code>php artisan drupal:validate</code>.</li></ol><table tabindex="0"><thead><tr><th>Removed</th><th>Replace with</th></tr></thead><tbody><tr><td><code>schema_version</code> 2</td><td><code>schema_version</code> 3</td></tr><tr><td><code>search.index.*</code> (<code>source</code>, <code>path</code>, <code>bundle_field</code>, <code>fulltext_field</code>)</td><td><code>index.*</code> in the extension&#39;s <code>config/drupal-search-api.php</code>. Without the extension, drop it.</td></tr><tr><td><code>search.index_lookup_pages</code></td><td><code>index.lookup_pages</code> in the extension.</td></tr><tr><td><code>search.match_strategy</code> and a type&#39;s <code>match_strategy</code></td><td>The extension&#39;s <code>index.match_strategy</code> and <code>content_types.&lt;key&gt;.match_strategy</code>. Core matches terms natively.</td></tr><tr><td><code>index_bundle</code></td><td><code>content_types.&lt;key&gt;.bundle</code> in the extension.</td></tr><tr><td><code>index_fields</code></td><td>Name the columns directly under <code>filters</code> in the extension.</td></tr><tr><td><code>index_field</code> of a <code>year_range</code> filter</td><td>Give the filter a <code>native_path</code>; the column goes in the extension.</td></tr><tr><td><code>index</code> of a <code>boolean</code> field</td><td>Keep <code>native</code>. A boolean without a <code>native</code> path is an error unless the extension is installed.</td></tr><tr><td><code>index</code> of a condition</td><td>Drop it; the column goes under <code>conditions</code> in the extension. A condition must name an <code>attribute</code>.</td></tr><tr><td><code>index_title_field</code></td><td>Rename it <code>title_attribute</code>.</td></tr><tr><td><code>related</code> on a content type</td><td>Drop it and pass props to <code>&lt;x-drupal::related&gt;</code>; see below.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Removed code</th><th>Replace with</th></tr></thead><tbody><tr><td><code>IndexRelatedStrategy</code>, <code>RelatedConfig</code>, <code>ContentType::related</code></td><td><code>RelatedContent</code>, <code>RelatedRequest</code>, <code>Criterion</code>; the extension supplies an index strategy.</td></tr><tr><td><code>MatchStrategy</code>, <code>SearchQueries</code></td><td><code>NativeQueries</code> and the <code>SearchBackend</code> seam.</td></tr><tr><td><code>Filter::indexField</code>, <code>BooleanField::index</code>, <code>Condition::index</code>, <code>ContentType::indexBundle</code>, <code>indexFields</code>, <code>indexTitleField</code>, <code>indexConditionQuery</code></td><td>The extension&#39;s <code>IndexDescriptor</code>.</td></tr><tr><td><code>FakesDrupal::fakeIndex()</code></td><td>The extension&#39;s <code>FakesIndex</code> trait. <code>fakeEntities()</code> and <code>fakeDocument()</code> are now <code>protected</code>.</td></tr></tbody></table><p>The <code>related</code> setting becomes props:</p><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-&#39;related&#39; =&gt; [&#39;relations&#39; =&gt; [&#39;topics&#39;, &#39;tracks&#39;], &#39;tie_break&#39; =&gt; &#39;-created&#39;, &#39;limit&#39; =&gt; 6],</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+&lt;x-drupal::related :entity=&quot;$talk&quot; :criteria=&quot;[&#39;topics&#39;, &#39;tracks&#39;]&quot; order=&quot;-created&quot; :limit=&quot;6&quot;/&gt;</span></span></code></pre></div><p><code>related.candidates</code> is gone: the native strategy takes at most <code>search.native_limit</code> items per request.</p><p>Other changes to review:</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th><th>What to do</th></tr></thead><tbody><tr><td>Filter-only searches are native</td><td>They page with a real offset and show <code>N+</code> until the last page.</td><td>Check views that print a total: <code>Listing::total</code> may be <code>null</code>; use <code>exact</code>.</td></tr><tr><td><code>SearchBackend</code> and <code>RelatedStrategy</code> are the seams</td><td>An extension plugs in without touching the fetcher.</td><td>None, unless you replaced the fetcher.</td></tr><tr><td><code>drupal:validate</code></td><td>New native probes and an <code>extensions</code> scope; index probes leave core.</td><td>Update scripts that parse the check names.</td></tr><tr><td><code>drupal.related.max_requests</code></td><td>New shared setting, default 12.</td><td>None.</td></tr></tbody></table><p>Check: <code>php artisan drupal:validate</code> prints no <code>FAIL</code> and a search for a typed term and a filter-only search both return results.</p><h2 id="_1-1-0-to-2-0-0" tabindex="-1">1.1.0 to 2.0.0 <a class="header-anchor" href="#_1-1-0-to-2-0-0" aria-label="Permalink to &quot;1.1.0 to 2.0.0&quot;">​</a></h2><p>This release removes the bookstore assumptions: the package now models any Drupal content. It is a breaking release and the descriptor moves to <code>schema_version</code> 2.</p><p>A version 1 descriptor fails at boot with one error that lists every removed key with its replacement. There are no shims. Fix each line, then run the steps above.</p><table tabindex="0"><thead><tr><th>Removed</th><th>Replace with</th></tr></thead><tbody><tr><td><code>schema_version</code> 1</td><td><code>schema_version</code> 2</td></tr><tr><td><code>facet_of</code> on a facet</td><td>Drop it. A Facet is any non-node entity type and is not tied to one primary. Relate the types with a relation and an <code>equals</code> filter.</td></tr><tr><td><code>count_field</code>, the built-in <code>count</code> and <code>Entity::$count</code></td><td>Declare the count as an ordinary field and hide empty entries with a <a href="./descriptor-reference#conditions"><code>conditions</code></a> rule.</td></tr><tr><td>The <code>any_flag</code> filter (<code>flags</code>, <code>group</code>)</td><td>A <code>boolean</code> filter with <code>fields</code> and <code>match</code>. See <a href="./descriptor-reference#filters">Filters</a>.</td></tr><tr><td>The <code>link</code> relation and the <code>Link</code> object</td><td>Model the related entity as a content type and reach it with a <code>content</code> relation; a paragraph without an alias is a facet with no routes.</td></tr><tr><td><code>search.on_sale_pages</code>, <code>onSale()</code>, <code>hasFlags()</code>, <code>onlyOnSale()</code></td><td><code>search.index_lookup_pages</code> and the index lookup names.</td></tr><tr><td><code>Descriptor::searchablePrimary()</code>, <code>SearchTabs::primary()</code>, <code>Descriptor::facetsOf()</code></td><td><code>Descriptor::searchableTypes()</code> and <code>SearchTabs::default()</code>.</td></tr><tr><td>&quot;Only a primary has filters or is searchable&quot;, &quot;exactly one searchable primary&quot;</td><td>Filters, sorts and <code>searchable</code> belong to the type. Search needs at least one searchable type.</td></tr></tbody></table><p>Other changes to review:</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th><th>What to do</th></tr></thead><tbody><tr><td>Role follows the entity type</td><td><code>node</code> is a primary and any other entity type is a facet. A facet is not searchable unless you set <code>searchable</code> to <code>true</code>.</td><td>Add <code>searchable =&gt; true</code> to each facet that had a search tab.</td></tr><tr><td>A facet without a path alias gets no route</td><td>Types such as a paragraph have <code>Entity::path</code> equal to <code>null</code> and <code>url()</code> throws.</td><td>Set <code>url_prefix</code> or <code>listing_path</code> to opt in.</td></tr><tr><td>Several searchable types</td><td>Each is a tab; <code>search.tabs</code> is optional. <code>match_strategy</code> can be set per type.</td><td>Review your tabs and the <code>search.suggestions.quotas</code>.</td></tr><tr><td><code>term_fields</code> default</td><td>A searchable type with none matches its title attribute at weight 1.</td><td>None.</td></tr><tr><td>New: <code>decorator</code>, <code>file</code> relation, dotted includes</td><td>See <a href="./entity-decorators">Entity decorators</a> and the <a href="./descriptor-reference#relations">Descriptor reference</a>.</td><td>Optional.</td></tr></tbody></table><p>Check: <code>php artisan drupal:validate</code> prints no <code>FAIL</code> and the search page shows a tab for each searchable type.</p><h2 id="_1-0-0-to-1-1-0" tabindex="-1">1.0.0 to 1.1.0 <a class="header-anchor" href="#_1-0-0-to-1-1-0" aria-label="Permalink to &quot;1.0.0 to 1.1.0&quot;">​</a></h2><p>This release adds the documentation site and a few safety checks. Nothing needs to change for an app that already works, except the item marked <strong>Action</strong>.</p><table tabindex="0"><thead><tr><th>Change</th><th>Effect</th><th>What to do</th></tr></thead><tbody><tr><td>Default <code>drupal.*</code> settings ship in the package</td><td>Timeouts, retries and cache windows have working defaults without a <code>config/drupal.php</code>. Your own file still wins, key by key.</td><td>Optional: delete the keys in your <code>config/drupal.php</code> that equal the defaults. See <a href="./installation#3-publish-the-configuration">Installation</a>.</td></tr><tr><td>Unknown keys produce warnings</td><td>A typo in <code>config/drupal-backend.php</code> shows in <code>drupal:validate</code> and in the descriptor smoke test, with a suggestion. Boot never fails because of it.</td><td>Run <code>php artisan drupal:validate</code> and fix the warnings.</td></tr><tr><td><code>drupal:validate</code> with an unknown Source name exits 1</td><td>It used to check nothing and exit 0. It now prints the declared Sources.</td><td>Update CI steps that pass a Source name.</td></tr><tr><td><code>search.term.min</code> sets the message</td><td>The &quot;enter at least N letters or numbers&quot; text follows the setting. <strong>Action:</strong> <code>SearchForm::TOO_SHORT</code> is removed.</td><td>Replace it with <code>SearchForm::tooShortMessage()</code> in your views.</td></tr><tr><td><code>drupal:contract</code> describes the webhook payload as <code>{&quot;changes&quot;: [...]}</code></td><td>Text only. The frontend still ignores the body.</td><td>Regenerate a committed <code>drupal-contract.md</code>.</td></tr><tr><td>A documentation route</td><td>Served outside production. Since 4.0.0 it lives at <code>/backend-docs</code> in the separate <code>proteo/drupal-backend-docs</code> package.</td><td>See <a href="#_3-3-1-to-4-0-0">3.3.1 to 4.0.0</a>.</td></tr><tr><td>Dist archives exclude the Markdown sources of <code>docs/</code></td><td>The built site stays in <code>public/</code>.</td><td>None.</td></tr></tbody></table><details><summary>The view change in detail</summary><div class="language-diff vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">diff</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#B31D28;--shiki-dark:#FDAEB7;">-{{ Proteo\\DrupalFront\\Livewire\\Forms\\SearchForm::TOO_SHORT }}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">+{{ Proteo\\DrupalFront\\Livewire\\Forms\\SearchForm::tooShortMessage() }}</span></span></code></pre></div></details><p>Check: the search page shows <code>Enter at least 2 letters or numbers.</code> for a one-letter term, and <code>php artisan drupal:validate</code> prints no <code>FAIL</code>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Look for problems in <a href="./troubleshooting">Troubleshooting</a>.</li><li>Check the backend after upgrading with <a href="./validation-in-ci-deploy">Validation in CI/deploy</a>.</li><li>Review every setting in the <a href="./configuration-reference">Configuration reference</a>.</li></ul>`,38)])])}const g=t(r,[["render",s]]);export{u as __pageData,g as default};
